CREATE DATABASE IF NOT EXISTS sig_banca CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sig_banca;

CREATE TABLE cursos (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, sigla VARCHAR(20) NOT NULL UNIQUE, ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT chk_curso_nome CHECK (CHAR_LENGTH(TRIM(nome)) >= 2), CONSTRAINT chk_curso_sigla CHECK (CHAR_LENGTH(TRIM(sigla)) BETWEEN 2 AND 20)
) ENGINE=InnoDB;
CREATE TABLE usuarios (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, perfil ENUM('aluno','orientador','avaliador','administrador') NOT NULL, matricula VARCHAR(50) NULL UNIQUE, curso_id INT UNSIGNED NULL, ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT chk_usuario_nome CHECK (CHAR_LENGTH(TRIM(nome)) >= 2), CONSTRAINT chk_usuario_email CHECK (email LIKE '%_@_%._%'), CONSTRAINT fk_usuario_curso FOREIGN KEY (curso_id) REFERENCES cursos(id) ON DELETE SET NULL, INDEX idx_usuario_perfil(perfil)
) ENGINE=InnoDB;
CREATE TABLE trabalhos (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titulo VARCHAR(255) NOT NULL, resumo TEXT NULL, curso_id INT UNSIGNED NOT NULL, orientador_id INT UNSIGNED NOT NULL, ano_letivo SMALLINT NOT NULL, semestre_letivo TINYINT NOT NULL, status ENUM('RASCUNHO','AGUARDANDO_CONFIRMACOES','CONFIRMADA','REALIZADA','AGUARDANDO_DOCUMENTOS','AGUARDANDO_CORRECOES','AGUARDANDO_VERSAO_FINAL','AGUARDANDO_APROVACAO','AJUSTES_SOLICITADOS','CONCLUIDA') NOT NULL DEFAULT 'RASCUNHO', publico TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT chk_trabalho_titulo CHECK (CHAR_LENGTH(TRIM(titulo)) >= 5), CONSTRAINT chk_trabalho_ano CHECK (ano_letivo BETWEEN 2000 AND 2200), CONSTRAINT chk_trabalho_semestre CHECK (semestre_letivo IN (1,2)), CONSTRAINT fk_trabalho_curso FOREIGN KEY(curso_id) REFERENCES cursos(id), CONSTRAINT fk_trabalho_orientador FOREIGN KEY(orientador_id) REFERENCES usuarios(id), INDEX idx_trabalho_filtros(curso_id,ano_letivo,semestre_letivo,status), INDEX idx_trabalho_orientador_status(orientador_id,status)
) ENGINE=InnoDB;
CREATE TABLE alunos_trabalhos (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trabalho_id INT UNSIGNED NOT NULL, aluno_id INT UNSIGNED NOT NULL, UNIQUE KEY uq_aluno_trabalho(trabalho_id,aluno_id), CONSTRAINT fk_at_trabalho FOREIGN KEY(trabalho_id) REFERENCES trabalhos(id) ON DELETE CASCADE, CONSTRAINT fk_at_aluno FOREIGN KEY(aluno_id) REFERENCES usuarios(id) ON DELETE CASCADE, INDEX idx_at_aluno(aluno_id,trabalho_id)
) ENGINE=InnoDB;
CREATE TABLE bancas (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trabalho_id INT UNSIGNED NOT NULL, data_banca DATE NOT NULL, hora_inicio TIME NOT NULL, hora_fim TIME NOT NULL, modalidade ENUM('presencial','online','hibrida') NOT NULL, local VARCHAR(255) NULL, link_online VARCHAR(500) NULL, status ENUM('AGUARDANDO_CONFIRMACOES','CONFIRMADA','REALIZADA','AGUARDANDO_DOCUMENTOS','AGUARDANDO_CORRECOES','AGUARDANDO_VERSAO_FINAL','AGUARDANDO_APROVACAO','AJUSTES_SOLICITADOS','CONCLUIDA') NOT NULL DEFAULT 'AGUARDANDO_CONFIRMACOES', realizada_em DATETIME NULL, criado_por INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT chk_banca_horario CHECK (hora_fim > hora_inicio), CONSTRAINT chk_banca_local CHECK (modalidade NOT IN ('presencial','hibrida') OR NULLIF(TRIM(local),'') IS NOT NULL), CONSTRAINT chk_banca_link CHECK (modalidade NOT IN ('online','hibrida') OR NULLIF(TRIM(link_online),'') IS NOT NULL), CONSTRAINT fk_banca_trabalho FOREIGN KEY(trabalho_id) REFERENCES trabalhos(id), CONSTRAINT fk_banca_criador FOREIGN KEY(criado_por) REFERENCES usuarios(id), INDEX idx_banca_data_status(data_banca,status), INDEX idx_banca_trabalho_data(trabalho_id,data_banca)
) ENGINE=InnoDB;
CREATE TABLE banca_avaliadores (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, banca_id INT UNSIGNED NOT NULL, avaliador_id INT UNSIGNED NOT NULL, funcao VARCHAR(60) NULL, status_resposta ENUM('pendente','aceito','recusado') NOT NULL DEFAULT 'pendente', respondido_em DATETIME NULL, UNIQUE KEY uq_banca_avaliador(banca_id,avaliador_id), CONSTRAINT fk_ba_banca FOREIGN KEY(banca_id) REFERENCES bancas(id) ON DELETE CASCADE, CONSTRAINT fk_ba_avaliador FOREIGN KEY(avaliador_id) REFERENCES usuarios(id), INDEX idx_ba_avaliador_status(avaliador_id,status_resposta)
) ENGINE=InnoDB;
CREATE TABLE convites (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, banca_avaliador_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expira_em DATETIME NULL, status ENUM('pendente','aceito','recusado','expirado','substituido') NOT NULL DEFAULT 'pendente', enviado_em DATETIME NULL, respondido_em DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_convite_ba FOREIGN KEY(banca_avaliador_id) REFERENCES banca_avaliadores(id) ON DELETE CASCADE, INDEX idx_convite_status(status)
) ENGINE=InnoDB;
CREATE TABLE documentos (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trabalho_id INT UNSIGNED NOT NULL, banca_id INT UNSIGNED NULL, tipo ENUM('ata','autorizacao_ric','trabalho','versao_final','outro') NOT NULL, nome_original VARCHAR(255) NOT NULL, nome_armazenado VARCHAR(100) NOT NULL UNIQUE, caminho_armazenado VARCHAR(255) NOT NULL, mime_type VARCHAR(120) NOT NULL, tamanho_bytes INT UNSIGNED NOT NULL, status_validacao ENUM('pendente','aprovado','correcao') NOT NULL DEFAULT 'pendente', enviado_por INT UNSIGNED NOT NULL, enviado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, validado_por INT UNSIGNED NULL, validado_em DATETIME NULL, observacao TEXT NULL, CONSTRAINT chk_doc_tamanho CHECK (tamanho_bytes > 0), CONSTRAINT chk_doc_nome CHECK (CHAR_LENGTH(TRIM(nome_original)) > 0), CONSTRAINT fk_doc_trabalho FOREIGN KEY(trabalho_id) REFERENCES trabalhos(id), CONSTRAINT fk_doc_banca FOREIGN KEY(banca_id) REFERENCES bancas(id) ON DELETE SET NULL, CONSTRAINT fk_doc_enviado FOREIGN KEY(enviado_por) REFERENCES usuarios(id), CONSTRAINT fk_doc_validado FOREIGN KEY(validado_por) REFERENCES usuarios(id) ON DELETE SET NULL, INDEX idx_doc_trabalho_tipo(trabalho_id,tipo)
) ENGINE=InnoDB;
CREATE TABLE correcoes (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trabalho_id INT UNSIGNED NOT NULL, banca_id INT UNSIGNED NULL, descricao TEXT NOT NULL, data_liberacao DATE NOT NULL, prazo_final DATE NOT NULL, status ENUM('aberta','entregue','concluida') NOT NULL DEFAULT 'aberta', registrado_por INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT chk_cor_prazo CHECK (prazo_final = DATE_ADD(data_liberacao, INTERVAL 15 DAY)), CONSTRAINT chk_cor_descricao CHECK (CHAR_LENGTH(TRIM(descricao)) > 0), CONSTRAINT fk_cor_trabalho FOREIGN KEY(trabalho_id) REFERENCES trabalhos(id), CONSTRAINT fk_cor_banca FOREIGN KEY(banca_id) REFERENCES bancas(id) ON DELETE SET NULL, CONSTRAINT fk_cor_user FOREIGN KEY(registrado_por) REFERENCES usuarios(id), INDEX idx_cor_prazo(prazo_final,status)
) ENGINE=InnoDB;
CREATE TABLE versoes (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trabalho_id INT UNSIGNED NOT NULL, documento_id INT UNSIGNED NOT NULL, numero_versao SMALLINT UNSIGNED NOT NULL, enviado_por INT UNSIGNED NOT NULL, enviado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('enviada','em_analise','aprovada','ajustes_solicitados') NOT NULL DEFAULT 'enviada', avaliado_por INT UNSIGNED NULL, avaliado_em DATETIME NULL, observacao_orientador TEXT NULL, UNIQUE KEY uq_versao_trabalho_numero(trabalho_id,numero_versao), CONSTRAINT fk_ver_trabalho FOREIGN KEY(trabalho_id) REFERENCES trabalhos(id), CONSTRAINT fk_ver_doc FOREIGN KEY(documento_id) REFERENCES documentos(id), CONSTRAINT fk_ver_envio FOREIGN KEY(enviado_por) REFERENCES usuarios(id), CONSTRAINT fk_ver_avaliador FOREIGN KEY(avaliado_por) REFERENCES usuarios(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE notificacoes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, usuario_id INT UNSIGNED NOT NULL, tipo VARCHAR(40) NOT NULL, titulo VARCHAR(160) NOT NULL, mensagem TEXT NOT NULL, link_interno VARCHAR(255) NULL, lida_em DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_not_user FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE, INDEX idx_not_user_lida(usuario_id,lida_em));
CREATE TABLE auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, usuario_id INT UNSIGNED NULL, acao VARCHAR(100) NOT NULL, entidade VARCHAR(60) NOT NULL, entidade_id INT UNSIGNED NULL, detalhes TEXT NULL, ip VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_user FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL, INDEX idx_audit_entity(entidade,entidade_id));
